[
  {
    "statement": "Multiple actions are reported to increase butterfly populations across farmland.",
    "citations": []
  },
  {
    "statement": "Cost-effectiveness comparisons of actions to increase butterfly populations on farmland are not reported.",
    "citations": []
  },
  {
    "statement": "Paying farmers to implement conservation measures, known as agri-environment schemes, was associated with higher butterfly and moth abundance in most studies across the UK, Switzerland, and Sweden.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Paying farmers to implement conservation measures was associated with higher butterfly and moth richness in most studies across the UK, Switzerland, and Sweden.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "The results of paying farmers to implement conservation measures for butterflies and moths can be mixed depending on the context.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Increasing or maintaining the proportion of natural or semi-natural habitat in a farmed landscape was associated with higher butterfly and moth abundance in most replicated studies.",
    "citations": [
      "3910"
    ]
  },
  {
    "statement": "Increasing or maintaining the proportion of natural or semi-natural habitat in a farmed landscape was associated with higher butterfly and moth richness in most studies across Europe and elsewhere.",
    "citations": [
      "3910"
    ]
  },
  {
    "statement": "Planting grass buffer strips or margins often increased butterfly abundance in multiple replicated studies.",
    "citations": [
      "3982"
    ]
  },
  {
    "statement": "Wider or floristically enhanced grass buffer strips or margins are particularly effective at increasing butterfly abundance.",
    "citations": [
      "3982"
    ]
  },
  {
    "statement": "Planting grass buffer strips or margins increased butterfly species richness in several studies.",
    "citations": [
      "3982"
    ]
  },
  {
    "statement": "The effects of planting grass buffer strips or margins can be context-dependent.",
    "citations": [
      "3982"
    ]
  },
  {
    "statement": "Converting to organic farming was associated with higher butterfly and moth abundance and richness in several replicated, site-comparison studies.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "The effects of converting to organic farming on butterfly and moth populations varied with landscape context.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "The effects of converting to organic farming on butterfly and moth populations varied with the time since conversion.",
    "citations": [
      "3907"
    ]
  }
]

